/** @jsxRuntime automatic */

import { useId, type ButtonHTMLAttributes, type ElementType } from 'react';
import { OverflowMenuVertical } from '@carbon-labs/react-motion-icons';
import { Menu, type MenuStyleProps } from './Menu';
import { menuSizeFor } from './menu-size';
import { useMenuTrigger } from '@carbon-labs/v12-motion';
import { iconSizeFor, useWithTimeScale } from '@carbon-labs/react-props';
import {
  useTriggerTooltip,
  type MenuTriggerProps,
  type MenuTriggerTooltipProps,
} from './trigger';

/* ============================================================================
 * OverflowMenu — v11's OverflowMenu (the v12 one, whose children are
 * MenuItems): an icon button that opens a Menu. The trigger is an icon
 * button with the rollover, its fill inset inside its box by the kit's inset;
 * a circle by default, 8px corners with `corners="rounded"`; its
 * motion icon plays on hover. Its label is its tooltip and its name
 * (`aria-labelledby`), as v11's (trigger.ts).
 * ========================================================================== */

export interface OverflowMenuProps
  extends
    MenuTriggerProps,
    MenuTriggerTooltipProps,
    Omit<
      ButtonHTMLAttributes<HTMLButtonElement>,
      'children' | 'onClick' | 'onKeyDown' | 'onPointerDown' | 'type'
    > {
  /** The trigger's tooltip and accessible name, and the menu's. Default `Options` (v11). */
  label?: string;
  /** The trigger's icon — a motion icon. Default OverflowMenuVertical. */
  renderIcon?: ElementType;
  /** The trigger's size, and its menu's (an xs trigger opens an sm menu). Default `md`. */
  size?: MenuTriggerProps['size'];
  /** Default `bottom-start` (v12's); `flipped` gives `bottom-end`. */
  menuAlignment?: 'top-start' | 'top-end' | 'bottom-start' | 'bottom-end';
  /** v11's classic flag: align the menu's end with the trigger's. */
  flipped?: boolean;
  // @carbon-proposal api: variant-prop — The colour treatment is one `variant` prop (inverse, tonal, outlined, hero, neutral or filled), so colour is never said by a role or a structure. TBD
  /** The menu's treatment (Menu's `variant`): `inverse` (default), `tonal`, `outlined`, `hero`. */
  variant?: MenuStyleProps['variant'];
}

export function OverflowMenu({
  children,
  label = 'Options',
  renderIcon: Icon = OverflowMenuVertical,
  size = 'md',
  menuAlignment,
  flipped,
  disabled,
  menuTarget,
  openFrom = 'pointer',
  menuSize,
  motion: motionProp,
  timeScale,
  onMove,
  onOpen,
  onClose,
  variant,
  lowContrast,
  corners,
  contour,
  outlinedFill,
  outline,
  shadow,
  tooltipAlignment,
  tooltipAutoAlign,
  className,
  onPointerEnter,
  onPointerLeave,
  onFocus,
  onBlur,
  // The menu's rows are loading (the trigger itself isn't).
  loading,
  skeletonCount,
  skeletonLabels,
  skeletonIcon,
  ...rest
}: OverflowMenuProps) {
  const motion = useWithTimeScale(motionProp, timeScale);
  const { open, setOpen, button, setButton, origin, initialFocus, handlers } =
    useMenuTrigger({
      openFrom,
      disabled,
      timeScale: motion?.timeScale,
    });
  const menuId = `cds-overflow-${useId().replace(/:/g, '')}`;
  const tip = useTriggerTooltip({
    label,
    off: !!disabled || open,
    align: tooltipAlignment,
    autoAlign: tooltipAutoAlign,
    buttonRef: setButton,
    own: { onPointerEnter, onPointerLeave, onFocus, onBlur },
    menu: handlers,
  });
  return (
    <>
      <button
        {...rest}
        {...tip.props}
        type="button"
        className={[
          'cds-menu-trigger',
          'cds-menu-trigger--icon',
          `cds-menu-trigger--${size}`,
          corners === 'square' && 'cds-menu-trigger--square',
          (corners ?? 'full') === 'full' && 'cds-menu-trigger--full',
          className,
        ]
          .filter(Boolean)
          .join(' ')}
        disabled={disabled}
        aria-labelledby={
          rest['aria-labelledby'] ?? tip.props['aria-labelledby']
        }
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={open ? menuId : undefined}
        data-motion-icon-frame="">
        <Icon size={iconSizeFor(size)} aria-hidden="true" />
      </button>
      {tip.tooltip}
      <Menu
        id={menuId}
        label={label}
        open={open}
        onOpen={onOpen}
        onClose={() => {
          setOpen(false);
          onClose?.();
        }}
        anchor={button}
        menuAlignment={
          menuAlignment ?? (flipped ? 'bottom-end' : 'bottom-start')
        }
        target={menuTarget}
        origin={origin}
        initialFocus={initialFocus}
        size={menuSizeFor(size, menuSize)}
        motion={motion}
        onMove={onMove}
        variant={variant}
        lowContrast={lowContrast}
        // Its menu is 8px whatever the trigger's shape: a pill only when
        // `corners` (or KitDefaults') asks for one.
        corners={corners}
        contour={contour}
        outlinedFill={outlinedFill}
        outline={outline}
        shadow={shadow}
        loading={loading}
        skeletonCount={skeletonCount}
        skeletonLabels={skeletonLabels}
        skeletonIcon={skeletonIcon}>
        {children}
      </Menu>
    </>
  );
}
OverflowMenu.displayName = 'OverflowMenu';
